fn inl_lbColl_DifferenceY<'a>(ctx: &'a Ctx, a: Vec<'a>, b: Vec<'a>) -> f64 {
    let mut a = a;
    let mut b = b;
    return fp::fsubs((a).y(), (b).y());
}

fn inl_sqrtf<'a>(ctx: &'a Ctx, x: f64) -> f64 {
    let mut x = x;
    let mut y: f64 = 0.0;
    if x > 0.0 {
        let mut guess: f64 = fp::frsqrte(x);
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(x, fp::fmul(guess, guess), 3.0)),
        );
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(x, fp::fmul(guess, guess), 3.0)),
        );
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(x, fp::fmul(guess, guess), 3.0)),
        );
        y = fp::frsp((fp::fmul(x, guess)));
        return y;
    }
    return x;
}

fn inl_sqrDistance<'a>(ctx: &'a Ctx, a: Vec<'a>, b: Vec<'a>) -> f64 {
    let mut a = a;
    let mut b = b;
    let mut x: f64 = fp::fsubs((a).x(), (b).x());
    let mut y: f64 = fp::fsubs((a).y(), (b).y());
    let mut z: f64 = fp::fsubs((a).z(), (b).z());
    return fp::fmadds(z, z, fp::fmadds(x, x, fp::fmuls(y, y)));
}

fn inl_sqrtf_store<'a>(ctx: &'a Ctx, x: f64, y: Val<'a, F32>) -> f64 {
    let mut x = x;
    let mut y = y;
    if x > 0.0 {
        let mut guess: f64 = fp::frsqrte(x);
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(x, fp::fmul(guess, guess), 3.0)),
        );
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(x, fp::fmul(guess, guess), 3.0)),
        );
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(x, fp::fmul(guess, guess), 3.0)),
        );
        (y).set(fp::frsp((fp::fmul(x, guess))));
        return (y).get();
    }
    return x;
}

